"""CRM models for search-request cases (ПСР штаб)."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime

from sqlalchemy import DateTime, Float, ForeignKey, Integer, String, Text
from sqlalchemy.orm import Mapped, mapped_column

from opentakserver.extensions import db
from opentakserver.functions import iso8601_string_from_datetime


CASE_STATUSES = ("new", "triage", "active", "suspended", "closed", "false_alarm")
CASE_PRIORITIES = ("low", "normal", "high", "critical")
CASE_SOURCES = ("web", "phone", "app")
CONTACT_ROLES = ("reporter", "witness", "missing", "relative", "other")


@dataclass
class CrmContact(db.Model):
    __tablename__ = "crm_contacts"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    full_name: Mapped[str] = mapped_column(String(255), nullable=False)
    phones: Mapped[str] = mapped_column(String(255), nullable=True)
    email: Mapped[str] = mapped_column(String(255), nullable=True)
    default_role: Mapped[str] = mapped_column(String(32), nullable=True)
    notes: Mapped[str] = mapped_column(Text, nullable=True)
    created_by: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    updated: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def to_json(self):
        return {
            "id": self.id,
            "full_name": self.full_name,
            "phones": self.phones,
            "email": self.email,
            "default_role": self.default_role,
            "notes": self.notes,
            "created_by": self.created_by,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
            "updated": iso8601_string_from_datetime(self.updated) if self.updated else None,
        }


@dataclass
class CrmCase(db.Model):
    __tablename__ = "crm_cases"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    case_number: Mapped[str] = mapped_column(String(64), unique=True, nullable=False)
    status: Mapped[str] = mapped_column(String(32), nullable=False, default="new")
    priority: Mapped[str] = mapped_column(String(32), nullable=False, default="normal")
    source: Mapped[str] = mapped_column(String(32), nullable=False, default="web")
    title: Mapped[str] = mapped_column(String(255), nullable=False)
    summary: Mapped[str] = mapped_column(Text, nullable=True)
    missing_name: Mapped[str] = mapped_column(String(255), nullable=True)
    missing_age: Mapped[str] = mapped_column(String(32), nullable=True)
    missing_sex: Mapped[str] = mapped_column(String(32), nullable=True)
    appearance: Mapped[str] = mapped_column(Text, nullable=True)
    clothing: Mapped[str] = mapped_column(Text, nullable=True)
    distinguishing: Mapped[str] = mapped_column(Text, nullable=True)
    medical: Mapped[str] = mapped_column(Text, nullable=True)
    last_seen_at: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    last_seen_place: Mapped[str] = mapped_column(Text, nullable=True)
    lkp_lat: Mapped[float] = mapped_column(Float, nullable=True)
    lkp_lon: Mapped[float] = mapped_column(Float, nullable=True)
    reporter_name: Mapped[str] = mapped_column(String(255), nullable=True)
    reporter_phone: Mapped[str] = mapped_column(String(64), nullable=True)
    assigned_username: Mapped[str] = mapped_column(String(255), nullable=True)
    mission_name: Mapped[str] = mapped_column(String(255), nullable=True)
    closed_reason: Mapped[str] = mapped_column(Text, nullable=True)
    created_by: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    updated: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    first_response_at: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def to_json(self):
        return {
            "id": self.id,
            "case_number": self.case_number,
            "status": self.status,
            "priority": self.priority,
            "source": self.source,
            "title": self.title,
            "summary": self.summary,
            "missing_name": self.missing_name,
            "missing_age": self.missing_age,
            "missing_sex": self.missing_sex,
            "appearance": self.appearance,
            "clothing": self.clothing,
            "distinguishing": self.distinguishing,
            "medical": self.medical,
            "last_seen_at": iso8601_string_from_datetime(self.last_seen_at)
            if self.last_seen_at
            else None,
            "last_seen_place": self.last_seen_place,
            "lkp_lat": self.lkp_lat,
            "lkp_lon": self.lkp_lon,
            "reporter_name": self.reporter_name,
            "reporter_phone": self.reporter_phone,
            "assigned_username": self.assigned_username,
            "mission_name": self.mission_name,
            "closed_reason": self.closed_reason,
            "created_by": self.created_by,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
            "updated": iso8601_string_from_datetime(self.updated) if self.updated else None,
            "first_response_at": iso8601_string_from_datetime(self.first_response_at)
            if self.first_response_at
            else None,
        }


@dataclass
class CrmCaseContact(db.Model):
    __tablename__ = "crm_case_contacts"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    case_id: Mapped[int] = mapped_column(Integer, ForeignKey("crm_cases.id"), nullable=False)
    contact_id: Mapped[int] = mapped_column(Integer, ForeignKey("crm_contacts.id"), nullable=False)
    role_in_case: Mapped[str] = mapped_column(String(32), nullable=False, default="other")
    notes: Mapped[str] = mapped_column(Text, nullable=True)

    def to_json(self):
        return {
            "id": self.id,
            "case_id": self.case_id,
            "contact_id": self.contact_id,
            "role_in_case": self.role_in_case,
            "notes": self.notes,
        }


@dataclass
class CrmEvent(db.Model):
    __tablename__ = "crm_events"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    case_id: Mapped[int] = mapped_column(Integer, ForeignKey("crm_cases.id"), nullable=False)
    event_type: Mapped[str] = mapped_column(String(64), nullable=False)
    body: Mapped[str] = mapped_column(Text, nullable=True)
    meta_json: Mapped[str] = mapped_column(Text, nullable=True)
    created_by: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def to_json(self):
        return {
            "id": self.id,
            "case_id": self.case_id,
            "event_type": self.event_type,
            "body": self.body,
            "meta_json": self.meta_json,
            "created_by": self.created_by,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
        }


@dataclass
class CrmAssignment(db.Model):
    __tablename__ = "crm_assignments"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    case_id: Mapped[int] = mapped_column(Integer, ForeignKey("crm_cases.id"), nullable=False)
    username: Mapped[str] = mapped_column(String(255), nullable=False)
    shift_label: Mapped[str] = mapped_column(String(128), nullable=True)
    status: Mapped[str] = mapped_column(String(32), nullable=False, default="active")
    assigned_by: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    ended: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def to_json(self):
        return {
            "id": self.id,
            "case_id": self.case_id,
            "username": self.username,
            "shift_label": self.shift_label,
            "status": self.status,
            "assigned_by": self.assigned_by,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
            "ended": iso8601_string_from_datetime(self.ended) if self.ended else None,
        }
